1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.model.Region;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
32	    @Mapping(target = "bulkSignupWarning", ignore = true)
33	    @Mapping(target = "identityKey", ignore = true)
34	    @Mapping(target = "possibleDuplicate", ignore = true)
35	    @Mapping(target = "possibleDuplicateOf", ignore = true)
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives the owner's {@code contactPreference} from the owner's own fields:
40	     * {@code EMAIL} when an email is present, otherwise {@code PHONE}.
41	     *
42	     * @param owner the owner being mapped
43	     * @return the derived contact preference
44	     */
45	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
46	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
47	    }
48	
49	    /**
50	     * Reports whether the owner has a usable {@code email}: present and not blank (whitespace-only).
51	     * The presence of an email drives several derived fields (such as the {@code contactPreference}
52	     * and the {@code membershipLevel}), so the "has an email" test is written in exactly one place
53	     * rather than repeated at each use.
54	     *
55	     * @param owner the owner being mapped
56	     * @return {@code true} when the owner has a non-blank email
57	     */
58	    default boolean hasEmail(Owner owner) {
59	        return owner.getEmail() != null && !owner.getEmail().isBlank();
60	    }
61	
62	    /**
63	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against the owner's
64	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} for 18 to 64, and
65	     * {@code SENIOR} for 65 and over. Returns {@code null} when no birth date is present, in which
66	     * case the field is absent from the response. The age in whole years is the number of complete
67	     * years between the birth date and the registration date (see {@link java.time.Period}); when the
68	     * registration date is somehow absent the current date is used as the reference.
69	     *
70	     * @param owner the owner being mapped
71	     * @return the derived age band, or {@code null} when no birth date is present
72	     */
73	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
74	        java.time.LocalDate birthDate = owner.getBirthDate();
75	        if (birthDate == null) {
76	            return null;
77	        }
78	        java.time.LocalDate reference = owner.getRegistrationDate() != null
79	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
80	        int age = java.time.Period.between(birthDate, reference).getYears();
81	        if (age < 18) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (age < 65) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
89	
90	    /**
91	     * Derives the owner's {@code locality} as the {@code REGION} segment of its {@code customerCode}
92	     * (the part before the {@code '-'}), which is the owner's canonical region code baked into the
93	     * region-and-hash identity {@code '<REGION>-<HASH8>'}. When no customer code is present (e.g. seed
94	     * data) it falls back to resolving the region directly from the owner's {@code postcode} and
95	     * {@code city} through the shared {@link Region#code(String, String)}. Reading the region from the
96	     * identity keeps the locality consistent with the code an owner is issued.
97	     *
98	     * @param owner the owner being mapped
99	     * @return the derived locality
100	     */
101	    default String locality(Owner owner) {
102	        String code = owner.getCustomerCode();
103	        if (code == null) {
104	            return Region.code(owner.getPostcode(), owner.getCity());
105	        }
106	        int dash = code.indexOf('-');
107	        return dash >= 0 ? code.substring(0, dash) : code;
108	    }
109	
110	    /**
111	     * Derives the owner's {@code membershipPoints} from the owner's factors. Starts at {@code 0},
112	     * adds {@code 2} when an email is present, adds {@code 1} when the owner's {@code namesakeCount}
113	     * is {@code 0}, adds {@code 2} for a household of {@code 3} or more (see
114	     * {@link Owner#getHouseholdSize()}), and adds {@code 3} when the owner's tenure &mdash; the number
115	     * of whole days between its {@code registrationDate} and the current date &mdash; exceeds
116	     * {@code 365}.
117	     *
118	     * @param owner the owner being mapped
119	     * @return the derived membership points
120	     */
121	    default Integer membershipPoints(Owner owner) {
122	        int points = 0;
123	        if (hasEmail(owner)) {
124	            points += 2;
125	        }
126	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
127	        if (uniqueName) {
128	            points += 1;
129	        }
130	        if (owner.getHouseholdSize() >= 3) {
131	            points += 2;
132	        }
133	        if (tenureDays(owner) > 365) {
134	            points += 3;
135	        }
136	        return points;
137	    }
138	
139	    /**
140	     * Maps the owner's {@code membershipPoints} to its numeric {@code membershipLevel}: level
141	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
142	     * {@code 4} for {@code 6} or more points.
143	     *
144	     * @param owner the owner being mapped
145	     * @return the derived membership level, between {@code 1} and {@code 4}
146	     */
147	    default Integer membershipLevel(Owner owner) {
148	        int points = membershipPoints(owner);
149	        if (points <= 1) {
150	            return 1;
151	        }
152	        if (points <= 3) {
153	            return 2;
154	        }
155	        if (points <= 5) {
